+			const x = -c / (2 * b);
+			if (x > 0 && x < limit) points.push(x);
+		}
+		points.sort((a, b) => a - b);
+		for (const face of [0, white]) {
+			const p = [a, b, c, d - face];
+			for (let i = 1; i < points.length; i++) {
